            "type": "CHANGE_REP_COUNT",
            "old_Reps": exercise_rep_count,
            "new_Reps": max(6, exercise_rep_count - 2),  # 不低于最小重复次数
            "adjust_reason": "用户疲劳但需增加力量"
        }
    else:
        adjustment = {
            "type": "CHANGE_REP_COUNT",
            "old_Reps": exercise_rep_count,
            "new_Reps": exercise_rep_count - 2,
            "adjust_reason": "用户疲劳，减少重复次数"
        }

# 检查质量评价点
if performance_data['most_frequent_error_type'] == '核心收紧不足':
    if quality_rating_points['squat_depth']['standard'] == 'high':
        adjustment = {
            "type": "CHANGE_QUALITY_STANDARD",
            "checkpoint_Id": "squat_depth",
            "old_standard": "high",
            "new_standard": "medium",
            "adjust_reason": "核心收紧不足，降低标准"
        }

# 输出结果
output = {
    "should_adjust": should_adjust,
    "reason": reason
}

if should_adjust and adjustment:
    output["adjustment"] = adjustment

print(json.dumps(output, ensure_ascii=False, indent=2))
```

